import React from 'react'
import { Alert, Box, Button, Card, Checkbox, Chip, FormControl, FormControlLabel, FormHelperText, Grid, InputLabel, LinearProgress, MenuItem, Select, SelectChangeEvent, Stack, TextField, Typography } from '@mui/material'
import { StatusMessage } from '@/components/StatusMessage'
import { ProfileFormSection } from './ProfileFormSection'
import ContactMailIcon from '@mui/icons-material/ContactMail'
import WorkIcon from '@mui/icons-material/Work'
import SchoolIcon from '@mui/icons-material/School'
import BadgeIcon from '@mui/icons-material/Badge';
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import RadioButtonUncheckedIcon from '@mui/icons-material/RadioButtonUnchecked';
import { UpdateProfilePayload, CastedUpdateProfilePayload, ProfileResult } from '@/types/profile.types'
import { CallStatus, Gender, ProfileType, SchoolData, Validator } from '@/types/api.types'
import { Schools } from '@/constants/StaticData'
import { GetUserId, SetProfileComplete } from '@/utils/token'
import { useProfilesStore, initialStateData, StateData } from '@/store';
import { ApiComponentStateManager, ApiGlobalStateManager } from '@/lib/api-state';
import { ensureMyProfileLoaded } from '@/lib/profile-cache';
import { ProfileServices, ProfileServicesError } from '@/api';
import { Pathname } from '@/constants/Routes';
import { useNavigate, useSearch } from '@tanstack/react-router';
import { IsProfileComplete } from '@/utils/token';
import { AppDialog } from '@/components/ui/AppDialog';
import { LocationAutocomplete } from '@/components/ui/LocationAutocomplete';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';

interface ProfileInfoUpdateProps {
    profileId?: string;
}

type SectionKey = 'navodaya' | 'contact' | 'education' | 'work';

const LockedHint: React.FC = () => (
    <FormHelperText sx={{ display: 'flex', alignItems: 'center', gap: 0.25 }}>
        <LockOutlinedIcon sx={{ fontSize: '0.8rem' }} /> Locked
    </FormHelperText>
);

export const ProfileInfoUpdate: React.FunctionComponent<ProfileInfoUpdateProps> = ({ profileId }) => {
    const { profileState, setProfileState } = useProfilesStore();
    const [formData, setFormData] = React.useState<UpdateProfilePayload>({} as UpdateProfilePayload);
    const [isFormValid, setIsFormValid] = React.useState<boolean>(false);
    const [isSubmitted, setIsSubmitted] = React.useState<boolean>(false);
    const [selectedSchools, setSelectedSchools] = React.useState<SchoolData[]>([]);
    const [showSuccessDialog, setShowSuccessDialog] = React.useState<boolean>(false);
    const [expanded, setExpanded] = React.useState<SectionKey | false>('navodaya');
    // Submit status for THIS form. Kept separate from the shared `profileState`
    // so an admin editing another member never overwrites their own cached
    // profile (which backs the sidebar, digital ID and /profile page).
    const [submitState, setSubmitState] = React.useState<StateData<ProfileResult>>(initialStateData<ProfileResult>());

    const userId = GetUserId();

    const navigate = useNavigate();
    const search = useSearch({ strict: false }) as Record<string, string>;
    // Capture once on mount so a re-render after SetProfileComplete() doesn't flip this to true.
    const wasIncompleteOnMountRef = React.useRef<boolean>(!IsProfileComplete());
    const schoolsHydratedRef = React.useRef<boolean>(false);

    // Lock core fields once the current user has stamped a self-edit.
    // Bulk-migrated profiles carry a legacy modifiedBy that won't equal `userId`,
    // so a userId match is sufficient — no separate "migration" heuristic needed.
    const isEditingOwnProfile = !profileId;
    const modifiedBy = profileState.data?.modifiedBy;
    const hasSelfEdited = isEditingOwnProfile && !!userId && modifiedBy === userId;
    const coreFieldsLocked = hasSelfEdited;
    // A verified profile freezes every field an admin vouched for; the API rejects
    // changes to them (ProfileAccessPolicy.FindFrozenIdentityChanges) regardless of this.
    const identityLocked = isEditingOwnProfile && profileState.data?.isVerified === true;
    const navodayaLocked = coreFieldsLocked || identityLocked;

    const handleSecondarySchoolIdsRemove = (schoolToDelete: SchoolData) => {
        const newSecondarySchoolIds = selectedSchools.filter((selectedSchools) => selectedSchools.UniqueId !== schoolToDelete.UniqueId);
        setSelectedSchools(newSecondarySchoolIds);
        const uniqueIds = newSecondarySchoolIds.map((school) => school.UniqueId);
        setFormData({ ...formData, otherJnvIds: uniqueIds });
        validateForm();
    };

    const handleSecondarySchoolIdsAdd = (schoolToAdd: SchoolData) => {
        if (!selectedSchools.find((selectedSchools) => selectedSchools.UniqueId === schoolToAdd.UniqueId)) {
            const newSecondarySchoolIds = [...selectedSchools, schoolToAdd];
            setSelectedSchools(newSecondarySchoolIds);
            const uniqueIds = newSecondarySchoolIds.map((school) => school.UniqueId);
            setFormData({ ...formData, otherJnvIds: uniqueIds });
        }
        validateForm();
    };

    const populateSelectedSchools = (profileData: any) => {
        if (profileData?.otherJnvIds) {
            const newSecondarySchools = profileData.otherJnvIds.map((uniqueId: number) => Schools.find((school) => school.UniqueId === uniqueId) as SchoolData);
            setSelectedSchools(newSecondarySchools);
        }
    }

    React.useEffect(() => {
        if (profileId) {
            // Admin editing another profile
            ProfileServices.GetAdminProfileById(profileId).then((response) => {
                if (response.data.status === 200 && response.data.result) {
                    setFormData(CastedUpdateProfilePayload(response.data.result));
                    populateSelectedSchools(response.data.result);
                }
            });
        } else if (profileState.status === CallStatus.Success && profileState.data.id) {
            setFormData(CastedUpdateProfilePayload(profileState.data));
            populateSelectedSchools(profileState.data);
        }
        else {
            void ensureMyProfileLoaded();
        }
    }, [profileId]);

    React.useEffect(() => {
        if (!profileId && profileState.data?.id) {
            setFormData(CastedUpdateProfilePayload(profileState.data));
            // Hydrate the secondary-school chips once, when the profile first arrives,
            // so a direct load of this page shows the saved selections.
            if (!schoolsHydratedRef.current) {
                schoolsHydratedRef.current = true;
                populateSelectedSchools(profileState.data);
            }
        }
    }, [formData.id, profileState.data, profileId])

    // Re-validate whenever form data changes so the Update button reflects the latest state.
    // Inline validateForm() calls in onChange handlers see stale formData (React state is async),
    // so we rely on this effect for accurate gating.
    React.useEffect(() => {
        validateForm();
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [formData, profileId]);

    // Validate the Update Profile Payload
    const validateForm = () => {
        // Admins editing other users can submit partial updates.
        if (profileId) {
            setIsFormValid(true);
            return true;
        }

        const isGeneralInfoValid: boolean = Validator.IsText(formData.name)
            && Validator.IsPhone(formData.phone)
            && Validator.IsText(formData.location)
            && Validator.IsText(formData.university)
            && Validator.IsText(formData.degree)

        const isAlumniInfoValid: boolean = isGeneralInfoValid
            && (formData.entryClass ?? 0) > 0
            && (formData.entryYear ?? 0) > 0
            && (formData.exitClass ?? 0) > (formData.entryClass ?? 0)
            && (formData.exitYear ?? 0) > (formData.entryYear ?? 0);

        const isStudentInfoValid: boolean = isGeneralInfoValid
            && (formData.entryClass ?? 0) > 0
            && (formData.entryYear ?? 0) > 0
            && (formData.exitClass ?? 0) === 0
            && (formData.exitYear ?? 0) === 0;

        const isStaffInfoValid: boolean = isGeneralInfoValid
            && Validator.IsText(formData.organisation)
            && Validator.IsText(formData.jobTitle);

        if (formData.profileType === ProfileType.Student) {
            setIsFormValid(isStudentInfoValid);
            return isGeneralInfoValid;
        }
        else if (formData.profileType === ProfileType.Staff) {

            setIsFormValid(isStaffInfoValid);
            return isStaffInfoValid;
        }
        else if (formData.profileType === ProfileType.Alumni) {
            setIsFormValid(isAlumniInfoValid);
            return isAlumniInfoValid;
        }
        else {
            setIsFormValid(isGeneralInfoValid);
            return isGeneralInfoValid;
        }
    }

    const handleProfileTypeChange = (e: SelectChangeEvent<ProfileType>) => {
        if (e.target.value === ProfileType.Student) {
            setFormData({ ...formData, profileType: e.target.value, isStudying: true, isWorking: false, exitClass: 0, exitYear: 0, university: '', degree: '', organisation: '', jobTitle: '' });
        }
        else if (e.target.value === ProfileType.Staff) {
            setFormData({ ...formData, profileType: e.target.value, isStudying: false, isWorking: true, exitClass: 0, exitYear: 0, organisation: 'Navodaya Vidyala Samiti' });
        }
        else {
            setFormData({ ...formData, profileType: e.target.value as ProfileType });
        }
    }

    // Handle Form Submit
    const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        if (validateForm()) {
            setIsSubmitted(true);
            if (profileId) {
                // Admin partial update — strip fields that would fail server validation
                // (empty Email would hit [EmailAddress]). The backend treats omitted fields
                // as "leave unchanged" (JSON Merge Patch semantics). Photo is uploaded via
                // a separate endpoint and is not part of UpdateProfilePayload.
                const adminPayload: UpdateProfilePayload = { ...formData };
                delete adminPayload.id;
                if (!adminPayload.email) delete adminPayload.email;
                // Admin updating another user: the response is that member's profile,
                // so it must stay in local state and never reach the shared store.
                ApiComponentStateManager(ProfileServices.UpdateProfileAdmin(profileId, adminPayload), setSubmitState);
            } else {
                const request = ProfileServices.UpdateProfile(formData);
                ApiComponentStateManager(request, setSubmitState);
                ApiGlobalStateManager(request, setProfileState).then(() => {
                    // Only treat this as completion when the update actually succeeded —
                    // ApiGlobalStateManager swallows failures, so check the resulting state.
                    if (useProfilesStore.getState().profileState.status !== CallStatus.Success) return;
                    SetProfileComplete();
                    window.dispatchEvent(new Event('auth-changed'));
                    // First-time profile completion: honor the redirect carried over from login.
                    if (wasIncompleteOnMountRef.current) {
                        const redirect = search?.redirect || Pathname.Root;
                        navigate({ to: redirect, replace: true });
                    }
                });
            }
        }
    }

    // Show success dialog after a successful update (admin edits and returning users).
    // First-time profile completion is excluded so the redirect from login can run instead.
    React.useEffect(() => {
        if (
            isSubmitted &&
            !wasIncompleteOnMountRef.current &&
            submitState.status === CallStatus.Success
        ) {
            setShowSuccessDialog(true);
        }
    }, [isSubmitted, submitState.status, profileId]);

    const handleSuccessDialogClose = () => {
        setShowSuccessDialog(false);
        if (!profileId) {
            navigate({ to: Pathname.Profile as string });
        }
    };

    // ── Section model: drives the collapsible cards, the progress bar and the summaries ──
    const isStudent = formData.profileType === ProfileType.Student;
    const isStaff = formData.profileType === ProfileType.Staff;
    const showEntryClass = isStudent || formData.profileType === ProfileType.Alumni;
    const showExitClass = formData.profileType === ProfileType.Alumni;
    const showExitYear = !!formData.profileType && !isStudent && !isStaff;
    const showEducation = !!formData.profileType && !isStudent;
    const showWork = showEducation;

    const navodayaComplete = Validator.IsText(formData.name)
        && !!formData.gender
        && !!formData.profileType
        && (formData.firstJnvId ?? 0) > 0
        && (formData.entryYear ?? 0) > 0
        && (!showEntryClass || (formData.entryClass ?? 0) > 0)
        && (!showExitClass || (formData.exitClass ?? 0) > (formData.entryClass ?? 0))
        && (!showExitYear || (formData.exitYear ?? 0) > (formData.entryYear ?? 0));
    const contactComplete = Validator.IsPhone(formData.phone) && Validator.IsText(formData.location);
    const educationComplete = Validator.IsText(formData.university) && Validator.IsText(formData.degree);
    const workComplete = !formData.isWorking || (Validator.IsText(formData.organisation) && Validator.IsText(formData.jobTitle));

    const entryJnv = Schools.find((school) => school.UniqueId === formData.firstJnvId);
    const yearRange = [formData.entryYear || null, showExitYear ? (formData.exitYear || null) : null].filter(Boolean).join(' \u2013 ');
    const navodayaSummary = [formData.name, entryJnv ? `JNV ${entryJnv.SchoolName}` : null, yearRange || null]
        .filter(Boolean).join(' \u00b7 ') || 'Add your name, school and batch';
    const contactSummary = [formData.phone, formData.location].filter(Boolean).join(' \u00b7 ') || 'Add phone and location';
    const educationSummary = [formData.degree, formData.university].filter(Boolean).join(' \u00b7 ') || 'Add your highest qualification';
    const workSummary = [formData.jobTitle, formData.organisation].filter(Boolean).join(' \u00b7 ') || 'Add your current or latest role';

    const sections = [
        { key: 'navodaya' as SectionKey, label: 'Navodaya', complete: navodayaComplete },
        { key: 'contact' as SectionKey, label: 'Contact', complete: contactComplete },
        ...(showEducation ? [{ key: 'education' as SectionKey, label: 'Education', complete: educationComplete }] : []),
        ...(showWork ? [{ key: 'work' as SectionKey, label: 'Work', complete: workComplete }] : []),
    ];
    const completedSections = sections.filter((section) => section.complete).length;

    const toggleSection = (key: SectionKey) => (isExpanded: boolean) => setExpanded(isExpanded ? key : false);

    // Open the first section that still needs input, once the profile has loaded.
    const didAutoExpandRef = React.useRef<boolean>(false);
    React.useEffect(() => {
        if (didAutoExpandRef.current || !formData.id) return;
        didAutoExpandRef.current = true;
        setExpanded(sections.find((section) => !section.complete)?.key ?? 'navodaya');
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [formData.id]);

    return (
        <Box>
            {formData.id ? (
                <form onSubmit={handleFormSubmit} onChange={validateForm}>
                    <Card variant="outlined" sx={{ borderRadius: 2, p: 2, mb: 2 }}>
                        <Stack direction="row" spacing={1} sx={{ alignItems: 'center', justifyContent: 'space-between', mb: 1 }}>
                            <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>Profile completeness</Typography>
                            <Typography variant="caption" color="text.secondary">
                                {completedSections} of {sections.length} sections
                            </Typography>
                        </Stack>
                        <LinearProgress
                            variant="determinate"
                            value={(completedSections / sections.length) * 100}
                            sx={{ height: 6, borderRadius: 3 }}
                        />
                        <Stack direction="row" sx={{ mt: 1.5, flexWrap: 'wrap', gap: 0.75 }}>
                            {sections.map((section) => (
                                <Chip
                                    key={section.key}
                                    size="small"
                                    clickable
                                    variant="outlined"
                                    color={section.complete ? 'success' : 'default'}
                                    icon={section.complete ? <CheckCircleIcon /> : <RadioButtonUncheckedIcon />}
                                    label={section.label}
                                    onClick={() => setExpanded(section.key)}
                                />
                            ))}
                        </Stack>
                    </Card>
                    <Stack spacing={1.5}>
                        <ProfileFormSection
                            icon={<BadgeIcon fontSize="small" />}
                            title="Navodaya Info"
                            summary={navodayaSummary}
                            complete={navodayaComplete}
                            visibility="public"
                            locked={navodayaLocked}
                            expanded={expanded === 'navodaya'}
                            onToggle={toggleSection('navodaya')}
                        >
                            {(navodayaLocked) && (
                                <Alert severity="info" icon={<LockOutlinedIcon fontSize="small" />} sx={{ mb: 2 }}>
                                    <Typography variant="caption">
                                        {identityLocked
                                            ? 'Your profile is verified, so your Navodaya details are locked. Contact an admin to update these.'
                                            : 'Name, Gender, Entry JNV and Entry Year are locked. Contact an admin to update these.'}
                                    </Typography>
                                </Alert>
                            )}
                            <Grid container spacing={2}>
                                <Grid size={{ xs: 12, sm: 6 }}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Name"
                                        required
                                        disabled={navodayaLocked}
                                        onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                                        error={!profileId && (formData.name ?? '').trim().length < 3}
                                        value={formData.name}
                                        helperText={navodayaLocked ? 'Locked' : undefined}
                                    />
                                </Grid>
                                <Grid size={{ xs: 12, sm: 6 }}>
                                    <FormControl fullWidth size="small" required error={!profileId && !formData.gender}>
                                        <InputLabel id="gender">Gender</InputLabel>
                                        <Select
                                            labelId="gender"
                                            id="gender-select"
                                            value={formData.gender}
                                            label="Gender"
                                            required
                                            disabled={navodayaLocked}
                                            onChange={(e) => { setFormData({ ...formData, gender: e.target.value }); validateForm(); }}
                                        >
                                            {Object.values(Gender).map((genderOption) => (
                                                <MenuItem key={genderOption} value={genderOption}>{genderOption}</MenuItem>
                                            ))}
                                        </Select>
                                        {navodayaLocked && <LockedHint />}
                                    </FormControl>
                                </Grid>
                                <Grid size={{ xs: 12, sm: 6 }}>
                                    <FormControl fullWidth size="small">
                                        <InputLabel id="profileType">Profile Type</InputLabel>
                                        <Select
                                            labelId="profileType"
                                            id="profileType-select"
                                            value={formData.profileType}
                                            label="Profile Type"
                                            required
                                            disabled={identityLocked}
                                            onChange={(e) => { handleProfileTypeChange(e); validateForm(); }}
                                        >
                                            <MenuItem key={ProfileType.Alumni} value={ProfileType.Alumni}>JNV Alumni</MenuItem>
                                            <MenuItem key={ProfileType.Student} value={ProfileType.Student}>Current JNV Student</MenuItem>
                                            <MenuItem key={ProfileType.ExStaff} value={ProfileType.ExStaff}>Former JNV Staff</MenuItem>
                                            <MenuItem key={ProfileType.Staff} value={ProfileType.Staff}>Current JNV Staff</MenuItem>
                                        </Select>
                                        {identityLocked && <LockedHint />}
                                    </FormControl>
                                </Grid>
                                <Grid size={{ xs: 12, sm: 6 }}>
                                    <FormControl fullWidth size="small">
                                        <InputLabel id="entryJNV">Entry JNV</InputLabel>
                                        <Select
                                            labelId="entryJNV"
                                            id="entryJNV-select"
                                            value={formData.firstJnvId}
                                            label="Entry JNV"
                                            required
                                            disabled={navodayaLocked}
                                            onChange={(e) => { setFormData({ ...formData, firstJnvId: Number(e.target.value) }); validateForm(); }}
                                        >
                                            {Schools.map((school) => (
                                                <MenuItem key={school.UniqueId} value={school.UniqueId}>[{school.StatePrefix}] JNV {school.SchoolName}</MenuItem>
                                            ))}
                                        </Select>
                                        {navodayaLocked && <LockedHint />}
                                    </FormControl>
                                </Grid>
                                {showEntryClass && (
                                    <Grid size={{ xs: 6, sm: 3 }}>
                                        <FormControl fullWidth size="small">
                                            <InputLabel id="entryClass">Entry class</InputLabel>
                                            <Select
                                                labelId="entryClass"
                                                id="entryClass-select"
                                                value={(formData.entryClass ?? 0).toString()}
                                                label="Entry class"
                                                required
                                                disabled={identityLocked}
                                                error={!profileId && (formData.profileType === ProfileType.Student ? false : (formData.exitClass ?? 0) <= (formData.entryClass ?? 0))}
                                                onChange={(e) => { setFormData({ ...formData, entryClass: parseInt(e.target.value) }); validateForm(); }}
                                            >
                                                {
                                                    Array.from(Array(12 - 6 + 1).keys()).map((i) => i + 6).map((entryClassOption) => (
                                                        <MenuItem key={entryClassOption} value={entryClassOption}>{entryClassOption}</MenuItem>
                                                    ))
                                                }
                                            </Select>
                                            {identityLocked && <LockedHint />}
                                        </FormControl>
                                    </Grid>
                                )}
                                {showExitClass && (
                                    <Grid size={{ xs: 6, sm: 3 }}>
                                        <FormControl fullWidth size="small">
                                            <InputLabel id="exitClass">Exit class</InputLabel>
                                            <Select
                                                labelId="exitClass"
                                                id="exitClass-select"
                                                value={(formData.exitClass ?? 0).toString()}
                                                label="Exit class"
                                                required
                                                disabled={identityLocked}
                                                error={!profileId && ((formData.exitClass ?? 0) <= (formData.entryClass ?? 0))}
                                                onChange={(e) => { setFormData({ ...formData, exitClass: parseInt(e.target.value) }); validateForm(); }}
                                            >
                                                {
                                                    Array.from(Array(12 - 6 + 1).keys()).map((i) => i + 6).map((exitClassOption) => (
                                                        <MenuItem key={exitClassOption} value={exitClassOption}>{exitClassOption}</MenuItem>
                                                    ))
                                                }
                                            </Select>
                                            {identityLocked && <LockedHint />}
                                        </FormControl>
                                    </Grid>
                                )}
                                <Grid size={{ xs: 6, sm: 3 }}>
                                    <FormControl fullWidth size="small">
                                        <InputLabel id="entryYear">Entry year</InputLabel>
                                        <Select
                                            labelId="entryYear"
                                            id="entryYear-select"
                                            value={(formData.entryYear ?? 0).toString()}
                                            label="Entry year"
                                            required
                                            disabled={navodayaLocked}
                                            error={!profileId && (formData.profileType === ProfileType.Student || formData.profileType === ProfileType.Staff ? false : (formData.exitYear ?? 0) <= (formData.entryYear ?? 0))}
                                            onChange={(e) => { setFormData({ ...formData, entryYear: parseInt(e.target.value) }); validateForm(); }}
                                        >
                                            {
                                                Array.from(Array((new Date()).getFullYear() - 1985 + 1).keys()).map((i) => i + 1985).map((entryYearOption) => (
                                                    <MenuItem key={entryYearOption} value={entryYearOption}>{entryYearOption}</MenuItem>
                                                ))
                                            }
                                        </Select>
                                        {navodayaLocked && <LockedHint />}
                                    </FormControl>
                                </Grid>
                                {showExitYear && (
                                    <Grid size={{ xs: 6, sm: 3 }}>
                                        <FormControl fullWidth size="small">
                                            <InputLabel id="exitYear">Exit year</InputLabel>
                                            <Select
                                                labelId="exitYear"
                                                id="exitYear-select"
                                                value={(formData.exitYear ?? 0).toString()}
                                                label="Exit year"
                                                error={!profileId && ((formData.exitYear ?? 0) <= (formData.entryYear ?? 0))}
                                                required
                                                disabled={identityLocked}
                                                onChange={(e) => { setFormData({ ...formData, exitYear: parseInt(e.target.value) }); validateForm(); }}
                                            >
                                                {
                                                    Array.from(Array((new Date()).getFullYear() - 1985 + 1).keys()).map((i) => i + 1985).map((exitYearOption) => (
                                                        <MenuItem key={exitYearOption} value={exitYearOption}>{exitYearOption}</MenuItem>
                                                    ))
                                                }
                                            </Select>
                                            {identityLocked && <LockedHint />}
                                        </FormControl>
                                    </Grid>
                                )}
                                <Grid size={{ xs: 12 }}>
                                    <FormControl fullWidth size="small">
                                        <InputLabel id="otherJNVs">Other JNVs attended</InputLabel>
                                        <Select
                                            labelId="otherJNVs"
                                            id="otherJNVs-select"
                                            label="Other JNVs attended"
                                            value="Add other JNVs attended"
                                            disabled={identityLocked}
                                            onChange={(e) => {
                                                if (e.target.value !== "Add other JNVs attended") {
                                                    handleSecondarySchoolIdsAdd(Schools.find((school) => school.UniqueId === Number(e.target.value)) as SchoolData);
                                                    validateForm();
                                                }
                                            }}
                                        >
                                            <MenuItem disabled value="Add other JNVs attended">Add other JNVs attended</MenuItem>
                                            {Schools.map((school) => (
                                                <MenuItem key={school.UniqueId} value={school.UniqueId}>[{school.StatePrefix}] JNV {school.SchoolName}</MenuItem>
                                            ))}
                                        </Select>
                                        {identityLocked && <LockedHint />}
                                    </FormControl>
                                    {selectedSchools.length > 0 && (
                                        <Stack direction="row" sx={{ flexWrap: 'wrap', gap: 0.75, mt: 1.25 }}>
                                            {selectedSchools.map((school) => (
                                                <Chip
                                                    key={school.UniqueId}
                                                    size="small"
                                                    label={`${school.StatePrefix} - ${school.SchoolName}`}
                                                    onDelete={identityLocked ? undefined : () => handleSecondarySchoolIdsRemove(school)}
                                                />
                                            ))}
                                        </Stack>
                                    )}
                                </Grid>
                            </Grid>
                        </ProfileFormSection>
                        <ProfileFormSection
                            icon={<ContactMailIcon fontSize="small" />}
                            title="Contact Info"
                            summary={contactSummary}
                            complete={contactComplete}
                            visibility={formData.isContactInfoVisible ? 'public' : 'private'}
                            expanded={expanded === 'contact'}
                            onToggle={toggleSection('contact')}
                        >
                            <Grid container spacing={2}>
                                <Grid size={{ xs: 12 }}>
                                    <FormControlLabel
                                        control={<Checkbox size="small" checked={!!formData.isContactInfoVisible}
                                            onChange={(e) => { setFormData({ ...formData, isContactInfoVisible: e.target.checked }); validateForm(); }} />}
                                        label={<Typography variant="body2">Visible to members</Typography>} />
                                </Grid>
                                <Grid size={{ xs: 12, sm: 6 }}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Email"
                                        disabled={!profileId}
                                        onChange={(e) => { setFormData({ ...formData, email: e.target.value }); validateForm(); }}
                                        value={formData.email || ''}
                                        helperText={profileId ? "Admins can update the email address" : "Email cannot be changed by the user"}
                                    />
                                </Grid>
                                <Grid size={{ xs: 12, sm: 6 }}>
                                    <TextField
                                        fullWidth
                                        size="small"
                                        label="Phone"
                                        placeholder="9876543210 or +123-9876543210"
                                        onChange={(e) => { setFormData({ ...formData, phone: e.target.value }); validateForm(); }}
                                        error={!profileId && !Validator.IsPhone(formData.phone)}
                                        value={formData.phone}
                                        helperText="India: 10 digits · Abroad: +countrycode-number"
                                    />
                                </Grid>
                                <Grid size={{ xs: 12 }}>
                                    <LocationAutocomplete
                                        value={formData.location ?? ''}
                                        error={!profileId && !Validator.IsText(formData.location)}
                                        onChange={(location, coordinates) => {
                                            setFormData({
                                                ...formData,
                                                location,
                                                latitude: coordinates?.latitude ?? 0,
                                                longitude: coordinates?.longitude ?? 0,
                                            });
                                        }}
                                    />
                                </Grid>
                            </Grid>
                        </ProfileFormSection>
                        {showEducation && (
                            <ProfileFormSection
                                icon={<SchoolIcon fontSize="small" />}
                                title="Highest Education"
                                summary={educationSummary}
                                complete={educationComplete}
                                visibility={formData.isHigherEducationInfoVisible ? 'public' : 'private'}
                                expanded={expanded === 'education'}
                                onToggle={toggleSection('education')}
                            >
                                <Grid container spacing={2}>
                                    <Grid size={{ xs: 12 }}>
                                        <Stack direction="row" sx={{ flexWrap: 'wrap', columnGap: 2 }}>
                                            <FormControlLabel
                                                control={<Checkbox size="small" checked={!!formData.isHigherEducationInfoVisible}
                                                    onChange={(e) => { setFormData({ ...formData, isHigherEducationInfoVisible: e.target.checked }); validateForm(); }} />}
                                                label={<Typography variant="body2">Visible to members</Typography>} />
                                            <FormControlLabel
                                                control={<Checkbox size="small" checked={!!formData.isStudying}
                                                    onChange={(e) => { setFormData({ ...formData, isStudying: e.target.checked }); validateForm(); }} />}
                                                label={<Typography variant="body2">Currently studying</Typography>} />
                                        </Stack>
                                    </Grid>
                                    <Grid size={{ xs: 12, sm: 6 }}>
                                        <TextField
                                            fullWidth
                                            size="small"
                                            label="University/College/School"
                                            onChange={(e) => { setFormData({ ...formData, university: e.target.value }); validateForm(); }}
                                            error={!profileId && !Validator.IsText(formData.university)}
                                            value={formData.university}
                                        />
                                    </Grid>
                                    <Grid size={{ xs: 12, sm: 6 }}>
                                        <TextField
                                            fullWidth
                                            size="small"
                                            label="Degree/Level"
                                            onChange={(e) => { setFormData({ ...formData, degree: e.target.value }); validateForm(); }}
                                            error={!profileId && !Validator.IsText(formData.degree)}
                                            value={formData.degree}
                                        />
                                    </Grid>
                                </Grid>
                            </ProfileFormSection>
                        )}
                        {showWork && (
                            <ProfileFormSection
                                icon={<WorkIcon fontSize="small" />}
                                title="Latest Employment"
                                summary={workSummary}
                                complete={workComplete}
                                visibility={formData.isEmploymentInfoVisible ? 'public' : 'private'}
                                expanded={expanded === 'work'}
                                onToggle={toggleSection('work')}
                            >
                                <Grid container spacing={2}>
                                    <Grid size={{ xs: 12 }}>
                                        <Stack direction="row" sx={{ flexWrap: 'wrap', columnGap: 2 }}>
                                            <FormControlLabel
                                                control={<Checkbox size="small" checked={!!formData.isEmploymentInfoVisible}
                                                    onChange={(e) => { setFormData({ ...formData, isEmploymentInfoVisible: e.target.checked }); validateForm(); }} />}
                                                label={<Typography variant="body2">Visible to members</Typography>} />
                                            <FormControlLabel
                                                control={<Checkbox size="small" checked={!!formData.isWorking}
                                                    onChange={(e) => { setFormData({ ...formData, isWorking: e.target.checked }); validateForm(); }} />}
                                                label={<Typography variant="body2">Currently working</Typography>} />
                                        </Stack>
                                    </Grid>
                                    <Grid size={{ xs: 12, sm: 6 }}>
                                        <TextField
                                            fullWidth
                                            size="small"
                                            label="Organisation"
                                            onChange={(e) => setFormData({ ...formData, organisation: e.target.value })}
                                            error={!profileId && (formData.isWorking ? !Validator.IsText(formData.organisation) : false)}
                                            value={formData.organisation}
                                        />
                                    </Grid>
                                    <Grid size={{ xs: 12, sm: 6 }}>
                                        <TextField
                                            fullWidth
                                            size="small"
                                            label="Job Title"
                                            onChange={(e) => { setFormData({ ...formData, jobTitle: e.target.value }); validateForm(); }}
                                            error={!profileId && (formData.isWorking ? !Validator.IsText(formData.jobTitle) : false)}
                                            value={formData.jobTitle}
                                        />
                                    </Grid>
                                </Grid>
                            </ProfileFormSection>
                        )}
                    </Stack>
                    <Card variant="outlined" sx={{ borderRadius: 2, mt: 2, p: 2 }}>
                        <Stack
                            direction={{ xs: 'column', sm: 'row' }}
                            spacing={1.5}
                            sx={{ alignItems: 'center', justifyContent: 'space-between' }}
                        >
                            <Typography variant="caption" color="text.secondary">
                                {isFormValid
                                    ? 'Everything looks good — save your changes.'
                                    : 'Some required fields still need your attention.'}
                            </Typography>
                            <Button
                                disabled={!isFormValid}
                                variant="contained"
                                type="submit"
                                sx={{ minWidth: 140, width: { xs: '100%', sm: 'auto' } }}
                            >
                                Update
                            </Button>
                        </Stack>
                        <StatusMessage
                            currentStatus={isSubmitted && submitState.status !== CallStatus.Success ? submitState.status : CallStatus.NotStarted}
                            notStartedMessage=""
                            successMessage=""
                            failureMessage={ProfileServicesError.UpdateProfileError(submitState.httpStatus)}
                            correlationId={submitState.correlationId}
                        />
                    </Card>
                </form>
            ) : !profileId && profileState.status === CallStatus.Failure ? (
                <Stack direction='column' spacing={2} sx={{ my: 2 }}>
                    <StatusMessage
                        currentStatus={CallStatus.Failure}
                        notStartedMessage=""
                        successMessage=""
                        failureMessage={ProfileServicesError.GetProfileError(profileState.httpStatus)}
                        correlationId={profileState.correlationId}
                    />
                </Stack>
            ) : (
                <Typography variant="body2" sx={{ color: 'text.secondary', p: 2 }}>Loading...</Typography>
            )}
            <AppDialog
                open={showSuccessDialog}
                onClose={handleSuccessDialogClose}
                title="Profile Updated"
                titleIcon={<CheckCircleIcon sx={{ color: 'success.main' }} />}
                actions={
                    <Button variant="contained" onClick={handleSuccessDialogClose} autoFocus>
                        {profileId ? 'Close' : 'View Profile'}
                    </Button>
                }
            >
                <Typography variant="body2">
                    {profileId ? 'Profile was updated successfully.' : 'Your profile was updated successfully.'}
                </Typography>
            </AppDialog>
        </Box>
    )
}

